import { gunzipSync } from 'node:zlib';

export type WardSeed = {
  code: number;
  name: string;
};

export type ProvinceSeed = {
  code: number;
  name: string;
  wards: WardSeed[];
};

// Official administrative dataset snapshot, stored compressed to keep the seed readable.
const compressedLocations =
  '';

export const locationsSeedData = JSON.parse(
  gunzipSync(Buffer.from(compressedLocations, 'base64')).toString('utf8'),
) as ProvinceSeed[];
